def solve(rows):
    filtered_rows = []
    for i, row in enumerate(rows):
        if i % 5 != 2 or i == len(rows) - 1:
            filtered_rows.append(row)

    rotated_rows = filtered_rows
    if rotated_rows:
        rotated_rows = rotated_rows[1:] + [rotated_rows[0]]

    key_value_pairs = {}
    for row in rotated_rows:
        parts = row.split('|')
        if len(parts) == 3:
            key = parts[0]
            try:
                value = int(parts[1])
                status = parts[2]
                if status == 'OK':
                    key_value_pairs[key] = value
            except ValueError:
                pass

    result = []
    for key, value in key_value_pairs.items():
        result.append([key, value])

    result.sort()
    return result

